import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { resourcesDir } from '../../lib/resources.js';
import type { Language, OptionDef } from '../../types.js';

/**
 * Creality Print's own option texts and translations, generated by `scripts/build-i18n.mjs` from the Creality Print
 * source (AGPL-3.0): `resources/crealityprint-option-text.json` (English tooltips and enum labels from
 * PrintConfig.cpp) and `resources/i18n/<lang>.json` (gettext msgid → msgstr from CrealityPrint_<lang>.po).
 */

interface OptionText {
  tooltip?: string;
  enumLabels?: string[];
}

let textCache: Record<string, OptionText> | null = null;

/** English tooltip / enum labels per option key. */
export function optionText(key: string): OptionText | undefined {
  if (!textCache) {
    const file = join(resourcesDir(), 'crealityprint-option-text.json');
    textCache = existsSync(file) ? ((JSON.parse(readFileSync(file, 'utf8')) as { options: Record<string, OptionText> }).options ?? {}) : {};
  }
  return Object.hasOwn(textCache, key) ? textCache[key] : undefined;
}

const catalogs = new Map<string, Record<string, string>>();

function catalog(lang: Language): Record<string, string> {
  let c = catalogs.get(lang);
  if (!c) {
    const file = join(resourcesDir(), 'i18n', `${lang}.json`);
    c = existsSync(file) ? ((JSON.parse(readFileSync(file, 'utf8')) as { messages: Record<string, string> }).messages ?? {}) : {};
    catalogs.set(lang, c);
  }
  return c;
}

/** Translates one Creality string; English (the msgid) when missing. */
export function translate(text: string, lang: Language): string {
  if (lang === 'en' || !text) return text;
  const c = catalog(lang);
  return (Object.hasOwn(c, text) ? c[text] : undefined) ?? (Object.hasOwn(c, text.trim()) ? c[text.trim()] : undefined) ?? text;
}

const localized = new Map<string, OptionDef[]>();

/** Option defs with label, tooltip, page, group and enum labels translated; keys, values and units untouched. */
export function localizeOptions(defs: OptionDef[], lang: Language, cacheKey: string): OptionDef[] {
  if (lang === 'en') return defs;
  const k = `${cacheKey}|${lang}|${defs.length}`;
  const hit = localized.get(k);
  if (hit) return hit;
  const t = (s: string) => translate(s, lang);
  const out = defs.map((d) => ({
    ...d,
    label: t(d.label),
    ...(d.tooltip && { tooltip: t(d.tooltip) }),
    page: t(d.page),
    group: t(d.group),
    ...(d.enumValues && { enumValues: d.enumValues.map((e) => ({ value: e.value, label: t(e.label) })) }),
  }));
  localized.set(k, out);
  return out;
}

export function parseLang(raw: unknown, fallback: Language): Language {
  return raw === 'es' || raw === 'en' ? raw : fallback;
}
